def _fm1_stand_in() -> Lme:
    raw = json.loads(_RESID_JSON)
    grouped = {key: tuple(vals) for key, vals in raw.items()}
    return Lme(grouped)


def one():
    out = ACF(_fm1_stand_in(), maxLag=11)
    return np.concatenate([out.lag, out.acf])


